<template><admin-goods-layout title="관리자 상세"><p v-if="errorMessage" class="error">{{ errorMessage }}</p><section v-if="admin" class="content-panel"><h2>{{ admin.adminName }}</h2><form @submit.prevent="save"><dl><dt>관리자번호</dt><dd>{{ admin.adminNo }}</dd><dt>아이디</dt><dd>{{ admin.adminId }}</dd><dt>이름</dt><dd>{{ admin.adminName }}</dd><dt>연락처</dt><dd><input v-model.trim="form.adminPhone"></dd><dt>부서</dt><dd><input v-model.trim="form.adminDepartment"></dd><dt>직책</dt><dd><input v-model.trim="form.adminPosition"></dd><dt>상태</dt><dd><input v-model.trim="form.adminStatus"></dd><dt>사용 여부</dt><dd><select v-model="form.useYn"><option value="Y">사용</option><option value="N">미사용</option></select></dd></dl><button :disabled="isSaving">{{ isSaving ? '저장 중...' : '저장' }}</button></form></section><router-link class="back" :to="{ name: 'adminAdminList' }">목록으로</router-link></admin-goods-layout></template>
<script>
import AdminGoodsLayout from '@/components/admin/AdminGoodsLayout.vue'
import { getAdmin, updateAdmin } from '@/api/admin'
export default { name: 'AdminAdminDetailView', components: { AdminGoodsLayout }, data: () => ({ admin: null, form: {}, isSaving: false, errorMessage: '' }), created () { this.load() }, methods: { load () { getAdmin(this.$route.params.adminNo).then(({ data }) => { this.admin = data; this.form = { adminPhone: data.adminPhone || '', adminDepartment: data.adminDepartment || '', adminPosition: data.adminPosition || '', adminStatus: data.adminStatus || '', useYn: data.useYn || 'Y' } }).catch(() => { this.errorMessage = '관리자 정보를 불러오지 못했습니다.' }) }, save () { this.isSaving = true; updateAdmin(this.admin.adminNo, this.form).then(() => this.load()).catch(() => { this.errorMessage = '저장에 실패했습니다.' }).finally(() => { this.isSaving = false }) } } }
</script>
<style scoped>.content-panel{margin-top:30px;padding:28px;background:#fff;border:1px solid #dce5e3}dl{display:grid;grid-template-columns:160px 1fr}dt,dd{margin:0;padding:14px;border-bottom:1px solid #e1e8e6}input,select{width:100%;max-width:360px;box-sizing:border-box;padding:9px}button,.back{display:inline-block;margin-top:20px;padding:12px 20px;background:#183c43;color:#fff;border:0;text-decoration:none}.error{color:#b14949}</style>
